"use client";

import { useEffect, useState } from "react";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { useAuth } from "@/components/AuthProvider";
import { createClient } from "@/lib/supabase/client";
import { useParams } from "next/navigation";
import PostCard from "@/components/PostCard";
import Link from "next/link";

type Profile = { id: string; username: string; display_name: string | null; bio: string | null; avatar_url: string | null; banner_url: string | null; website: string | null; location: string | null; created_at: string };
type Post = { id: string; content: string; created_at: string; author_id: string; media_urls?: string[] | null; profiles?: { username: string; display_name: string | null; avatar_url: string | null } | null };

export default function ProfileClient() {
  const { username } = useParams<{ username: string }>();
  const { user } = useAuth();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [tab, setTab] = useState<"posts" | "replies" | "media" | "likes">("posts");
  const [posts, setPosts] = useState<Post[]>([]);
  const [replies, setReplies] = useState<Post[]>([]);
  const [likes, setLikes] = useState<Post[]>([]);
  const [counts, setCounts] = useState({ followers: 0, following: 0 });
  const [isFollowing, setIsFollowing] = useState(false);
  const [followBusy, setFollowBusy] = useState(false);
  const [listType, setListType] = useState<'followers' | 'following' | null>(null);
  const [listProfiles, setListProfiles] = useState<any[]>([]);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState('');

  useEffect(() => {
    const run = async () => {
      const supabase = createClient();
      if (!supabase) { setError("Supabase not configured."); setLoading(false); return; }
      const { data: prof } = await supabase.from("profiles").select("*").eq("username", username).maybeSingle();
      if (!prof) { setError("Profile not found."); setLoading(false); return; }
      setProfile(prof as Profile);

      const { count: followers, error: followersError } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("following_id", prof.id);
      const { count: following, error: followingError } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("follower_id", prof.id);
      if (followersError || followingError) setError((followersError || followingError)?.message || "Could not load follow counts.");
      setCounts({ followers: followers ?? 0, following: following ?? 0 });

      if (user && user.id !== prof.id) {
        const { data: existing } = await supabase.from("follows").select("follower_id").eq("follower_id", user.id).eq("following_id", prof.id).maybeSingle();
        setIsFollowing(!!existing);
      }

      const { data: ps } = await supabase.from("posts").select("*").eq("author_id", prof.id).order("created_at", { ascending: false });
      const mappedPosts = (ps ?? []).map((p: any) => ({ ...p, profiles: prof }));
      setPosts(mappedPosts as Post[]);

      const { data: rs } = await supabase.from("replies").select("*").eq("author_id", prof.id).order("created_at", { ascending: false });
      const mappedReplies = (rs ?? []).map((r: any) => ({ id: r.id, content: r.content, created_at: r.created_at, author_id: r.author_id, media_urls: null, profiles: prof }));
      setReplies(mappedReplies as Post[]);

      const { data: likedRows } = await supabase.from("likes").select("post_id").eq("user_id", prof.id);
      const likedIds = (likedRows ?? []).map((r: any) => r.post_id);
      if (likedIds.length) {
        const { data: likedPosts } = await supabase.from("posts").select("*").in("id", likedIds);
        const mappedLikes = (likedPosts ?? []).map((p: any) => ({ ...p, profiles: null }));
        setLikes(mappedLikes as Post[]);
      } else {
        setLikes([]);
      }

      setLoading(false);
    };
    run();
  }, [username, user]);

  async function openList(type: 'followers' | 'following') {
    if (!profile) return;
    const supabase = createClient();
    if (!supabase) return;
    setListType(type);
    setListLoading(true);
    setListError('');
    setListProfiles([]);
    const column = type === 'followers' ? 'follower_id' : 'following_id';
    const filterColumn = type === 'followers' ? 'following_id' : 'follower_id';
    const { data: rows, error } = await supabase.from('follows').select(column).eq(filterColumn, profile.id);
    if (error) { setListError(error.message); setListLoading(false); return; }
    const ids = (rows ?? []).map((r: any) => r[column]);
    if (ids.length === 0) { setListLoading(false); return; }
    const { data: profs, error: pError } = await supabase.from('profiles').select('id,username,display_name,avatar_url').in('id', ids);
    if (pError) { setListError(pError.message); setListLoading(false); return; }
    setListProfiles(profs ?? []);
    setListLoading(false);
  }

  async function toggleFollow() {
    if (!user || !profile || user.id === profile.id) return;
    const supabase = createClient();
    if (!supabase) return;
    setFollowBusy(true);
    if (isFollowing) {
      const { error } = await supabase.from("follows").delete().eq("follower_id", user.id).eq("following_id", profile.id);
      if (error) { setError(error.message); setFollowBusy(false); return; }
      setIsFollowing(false);
      setCounts((c) => ({ ...c, followers: Math.max(0, c.followers - 1) }));
    } else {
      const { error } = await supabase.from("follows").insert({ follower_id: user.id, following_id: profile.id });
      if (error) { setError(error.message); setFollowBusy(false); return; }
      setIsFollowing(true);
      setCounts((c) => ({ ...c, followers: c.followers + 1 }));
    }
    setFollowBusy(false);
  }

  if (loading) {
    return (
      <Shell>
        <PageHeader title="Profile" />
        <div className="p-8 text-center text-sm text-af-muted">Loading profile…</div>
      </Shell>
    );
  }

  if (error || !profile) {
    return (
      <Shell>
        <PageHeader title="Profile" />
        <EmptyState title="Profile not found" body="This user may not exist or is unavailable." />
      </Shell>
    );
  }

  const isOwn = user?.id === profile.id;
  const mediaItems = posts.flatMap((p) => (p.media_urls ?? []).map((u) => ({ url: u, post: p })));

  return (
    <Shell>
      <PageHeader title={profile.display_name || profile.username} subtitle={`@${profile.username}`} />
      <div className="relative">
        {profile.banner_url ? (
          <img src={profile.banner_url} alt="" className="h-40 w-full object-cover" />
        ) : (
          <div className="h-40 w-full bg-af-surface" />
        )}
        <div className="absolute -bottom-12 left-4">
          {profile.avatar_url ? (
            <img src={profile.avatar_url} alt="" className="h-24 w-24 rounded-full border-4 border-af-bg object-cover" />
          ) : (
            <div className="h-24 w-24 rounded-full border-4 border-af-bg bg-af-surface-2" />
          )}
        </div>
      </div>
      <div className="px-4 pb-4 pt-16">
        <div className="flex items-start justify-between gap-3">
          <div>
            <h1 className="text-xl font-extrabold text-af-text">{profile.display_name || profile.username}</h1>
            <p className="text-af-muted">@{profile.username}</p>
          </div>
          {isOwn ? (
            <Link href="/settings" className="rounded-full border border-af-border px-4 py-1.5 text-sm font-bold text-af-text transition-colors hover:bg-af-surface-2">
              Edit profile
            </Link>
          ) : (
            <button
              onClick={toggleFollow}
              disabled={followBusy}
              className={`rounded-full px-4 py-1.5 text-sm font-bold transition-colors disabled:opacity-50 ${isFollowing ? "border border-af-border text-af-text hover:bg-af-surface-2" : "bg-af-brand text-white hover:bg-af-brand-hover"}`}
            >
              {followBusy ? "..." : isFollowing ? "Following" : "Follow"}
            </button>
          )}
        </div>
        {profile.bio && <p className="mt-3 whitespace-pre-wrap text-[15px] text-af-text">{profile.bio}</p>}
        <div className="mt-3 flex flex-wrap gap-3 text-sm text-af-muted">
          {profile.website && <a href={profile.website} className="text-af-accent hover:underline">{profile.website.replace(/^https?:\/\//, "")}</a>}
          {profile.location && <span>{profile.location}</span>}
          <span>Joined {new Date(profile.created_at).toLocaleDateString()}</span>
        </div>
        <div className="mt-3 flex gap-4 text-sm">
          <button onClick={() => openList('followers')} className="text-left"><strong className="text-af-text">{counts.followers}</strong> <span className="text-af-muted">Followers</span></button>
          <button onClick={() => openList('following')} className="text-left"><strong className="text-af-text">{counts.following}</strong> <span className="text-af-muted">Following</span></button>
        </div>
      </div>

      <div className="flex border-b border-af-border">
        {(["posts", "replies", "media", "likes"] as const).map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={`relative flex-1 py-3 text-sm font-medium capitalize transition-colors hover:bg-af-surface-2 ${tab === t ? "text-af-text" : "text-af-muted"}`}
          >
            {t}
            {tab === t && <div className="absolute bottom-0 left-1/2 h-0.5 w-12 -translate-x-1/2 rounded-full bg-af-brand" />}
          </button>
        ))}
      </div>

      {tab === "media" ? (
        mediaItems.length === 0 ? (
          <EmptyState title="No media yet" body="Media this user posts will appear here." />
        ) : (
          <div className="grid grid-cols-3 gap-0.5 p-0.5">
            {mediaItems.map((item, index) => (
              <Link key={item.url + index} href={`/${profile.username}/status/${item.post.id}`} className="aspect-square overflow-hidden bg-af-surface-2">
                {/\.(mp4|webm|mov)$/i.test(item.url) ? (
                  <div className="relative h-full w-full">
                    <video src={item.url} className="h-full w-full object-cover" />
                    <span className="absolute inset-0 flex items-center justify-center text-3xl text-white drop-shadow-lg">▶</span>
                  </div>
                ) : (
                  <img src={item.url} alt="" className="h-full w-full object-cover" />
                )}
              </Link>
            ))}
          </div>
        )
      ) : tab === "replies" ? (
        replies.length === 0 ? <EmptyState title="No replies yet" body="Replies will appear here." /> : <div>{replies.map((p) => <PostCard key={p.id} post={p} />)}</div>
      ) : tab === "likes" ? (
        likes.length === 0 ? <EmptyState title="No likes yet" body="Liked posts will appear here." /> : <div>{likes.map((p) => <PostCard key={p.id} post={p} />)}</div>
      ) : posts.length === 0 ? (
        <EmptyState title="No posts yet" body="Posts will appear here." />
      ) : (
        <div>{posts.map((p) => <PostCard key={p.id} post={p} />)}</div>
      )}
    {listType && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4" onClick={() => setListType(null)}>
        <div className="w-full max-w-md rounded-2xl border border-af-border bg-af-surface p-4" onClick={(e) => e.stopPropagation()}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-bold capitalize text-af-text">{listType}</h2>
            <button onClick={() => setListType(null)} className="text-af-muted hover:text-af-text">Close</button>
          </div>
          {listLoading ? <p className="mt-4 text-sm text-af-muted">Loading…</p> : listError ? <p className="mt-4 text-sm text-af-danger">{listError}</p> : listProfiles.length === 0 ? <p className="mt-4 text-sm text-af-muted">No accounts found.</p> : (
            <div className="mt-4 space-y-3">
              {listProfiles.map((p) => (
                <div key={p.id} className="flex items-center gap-3">
                  <Link href={`/${p.username}`} className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-af-surface-2">
                    {p.avatar_url ? <img src={p.avatar_url} alt="" className="h-full w-full object-cover" /> : null}
                  </Link>
                  <div className="min-w-0 flex-1">
                    <Link href={`/${p.username}`} className="block truncate text-sm font-bold hover:underline">{p.display_name || p.username}</Link>
                    <p className="truncate text-xs text-af-muted">@{p.username}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    )}
    </Shell>
  );
}

"use client";
import { useEffect, useState } from "react";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { createClient } from "@/lib/supabase/client";
import { useParams } from "next/navigation";
import Link from "next/link";

type Post = { id: string; content: string; created_at: string; author_id: string; media_urls?: string[] | null; profiles?: { username: string; display_name: string | null; avatar_url: string | null } | null };

export default function PostClient() {
  const { username, id } = useParams<{ username: string; id: string }>();
  const [post, setPost] = useState<Post | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const run = async () => {
      const supabase = createClient();
      if (!supabase) { setError("Supabase not configured."); setLoading(false); return; }
      const { data: p, error: pe } = await supabase.from("posts").select("*").eq("id", id).single();
      if (pe || !p) { setError("Post not found."); setLoading(false); return; }
      const { data: prof } = await supabase.from("profiles").select("*").eq("id", p.author_id).maybeSingle();
      if (!prof || prof.username !== username) { setError("Post not found."); setLoading(false); return; }
      setPost({ ...p, profiles: prof });
      setLoading(false);
    };
    run();
  }, [username, id]);

  if (loading) return <Shell><PageHeader title="Post" /><div className="p-8 text-center text-sm text-af-muted">Loading…</div></Shell>;
  if (error || !post) return <Shell><PageHeader title="Post" /><EmptyState title="Post not found" body="This post may have been removed or is unavailable." /></Shell>;

  return (
    <Shell>
      <PageHeader title="Post" />
      <article className="border-b border-af-border px-4 py-3">
        <div className="flex gap-3">
          <Link href={`/${post.profiles?.username}`} className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-af-surface-2">
            {post.profiles?.avatar_url ? <img src={post.profiles.avatar_url} alt="" className="h-full w-full object-cover" /> : null}
          </Link>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-1 text-[15px]">
              <Link href={`/${post.profiles?.username}`} className="font-bold hover:underline">{post.profiles?.display_name || post.profiles?.username}</Link>
              <span className="text-af-muted">@{post.profiles?.username}</span>
            </div>
            <p className="mt-2 whitespace-pre-wrap break-words text-[17px]">{post.content}</p>
          </div>
        </div>
      </article>
    </Shell>
  );
}

