"use client";
import { useEffect, useState } from "react";
import { Suspense } from "react";
import { useParams } from "next/navigation";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { useAuth } from "@/components/AuthProvider";
import { createClient } from "@/lib/supabase/client";
import Link from "next/link";
import PostCard from "@/components/PostCard";

type Post = {
  id: string;
  content: string;
  created_at: string;
  author_id: string;
  media_urls?: string[] | null;
  profiles?: { username: string; display_name: string | null; avatar_url: string | null } | null;
};
type Reply = {
  id: string;
  content: string;
  created_at: string;
  author_id: string;
  post_id: string;
  profiles?: { username: string; display_name: string | null; avatar_url: string | null } | null;
};

function PostPageInner() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [post, setPost] = useState<Post | null>(null);
  const [replies, setReplies] = useState<Reply[]>([]);
  const [draft, setDraft] = useState("");
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  async function load() {
    const supabase = createClient();
    if (!supabase) {
      setError("Supabase not configured.");
      setLoading(false);
      return;
    }
    const { data: p, error: pe } = await supabase.from("posts").select("*").eq("id", id).single();
    if (pe) {
      setError(pe.message);
      setLoading(false);
      return;
    }
    const authorIds = [p.author_id];
    let profMap = new Map();
    const { data: profs } = await supabase.from("profiles").select("*").in("id", authorIds);
    profMap = new Map((profs ?? []).map((x: any) => [x.id, x]));
    setPost({ ...p, profiles: profMap.get(p.author_id) || null } as Post);

    const { data: r } = await supabase.from("replies").select("*").eq("post_id", id).order("created_at", { ascending: true });
    const rIds = [...new Set((r ?? []).map((x: any) => x.author_id))];
    let rProfMap = new Map();
    if (rIds.length) {
      const { data: rprofs } = await supabase.from("profiles").select("*").in("id", rIds);
      rProfMap = new Map((rprofs ?? []).map((x: any) => [x.id, x]));
    }
    setReplies(
      ((r ?? []).map((x: any) => ({ ...x, profiles: rProfMap.get(x.author_id) || null })) as Reply[])
    );
    setLoading(false);
  }

  useEffect(() => {
    load();
  }, [id]);

  async function submit() {
    const text = draft.trim();
    if (!text) return;
    const supabase = createClient();
    if (!supabase || !user) {
      setError("Sign in to reply.");
      return;
    }
    setSubmitting(true);
    setError("");
    const { error } = await supabase.from("replies").insert({ post_id: id, author_id: user.id, content: text });
    if (!error && post?.author_id && post.author_id !== user.id) {
      const { data: existing } = await supabase.from("notifications").select("id").eq("user_id", post.author_id).eq("type", "reply").contains("payload", { actor_id: user.id, post_id: id }).limit(1);
      if (!existing || !existing.length) await supabase.from("notifications").insert({ user_id: post.author_id, type: "reply", payload: { actor_id: user.id, post_id: id }, read: false });
    }
    if (error) {
      setError(error.message);
      setSubmitting(false);
      return;
    }
    setDraft("");
    setSubmitting(false);
    load();
  }

  return (
    <Shell>
      <PageHeader title="Post" />
      {loading ? (
        <div className="p-8 text-center text-sm text-af-muted">Loading…</div>
      ) : !post ? (
        <EmptyState title="Post not found" body="This post may have been removed or is unavailable." />
      ) : (
        <div>
          <article className="border-b border-af-border px-4 py-3">
            <div className="flex gap-3">
              <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-af-surface-2">
                {post.profiles?.avatar_url ? (
                  <img src={post.profiles.avatar_url} alt="" className="h-full w-full object-cover" />
                ) : (
                  <div className="h-full w-full bg-gradient-to-br from-af-accent to-af-accent-2" />
                )}
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-1 text-[15px]">
                  <span className="truncate font-bold text-af-text">{post.profiles?.display_name || post.profiles?.username || "Unknown"}</span>
                  <span className="truncate text-af-muted">@{post.profiles?.username || "unknown"}</span>
                </div>
                <p className="mt-2 whitespace-pre-wrap break-words text-[17px] leading-normal text-af-text">{post.content}</p>
                {post.media_urls && post.media_urls.length > 0 && (
                  <div className="mt-3 overflow-hidden rounded-2xl border border-af-border">
                    {post.media_urls.map((u) => (
                      <img key={u} src={u} alt="" className="max-h-[510px] w-full object-cover" />
                    ))}
                  </div>
                )}
                <p className="mt-3 text-[15px] text-af-muted">{new Date(post.created_at).toLocaleString()}</p>
              </div>
            </div>
          </article>

          {user ? (
            <div className="border-b border-af-border px-4 py-3">
              <div className="flex gap-3">
                <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-af-surface-2">
                  <div className="h-full w-full bg-gradient-to-br from-af-accent to-af-accent-2" />
                </div>
                <div className="flex-1">
                  <textarea
                    value={draft}
                    onChange={(e) => setDraft(e.target.value)}
                    placeholder="Post your reply"
                    className="w-full resize-none bg-transparent text-[17px] outline-none placeholder:text-af-muted"
                    rows={3}
                  />
                  <div className="mt-2 flex justify-end border-t border-af-border pt-2">
                    <button
                      onClick={submit}
                      disabled={!draft.trim() || submitting}
                      className="rounded-full bg-af-accent px-5 py-1.5 text-[15px] font-bold text-white transition-colors hover:bg-af-accent-hover disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      {submitting ? "Replying..." : "Reply"}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="border-b border-af-border p-4 text-center">
              <Link href="/signin" className="text-af-accent hover:underline">
                Sign in to reply
              </Link>
            </div>
          )}

          {error && <div className="border-b border-af-border px-4 py-3 text-sm text-af-danger">{error}</div>}

          {replies.length === 0 ? (
            <EmptyState title="No replies yet" body="Be the first to reply." />
          ) : (
            <div>
              {replies.map((r) => (
                <article key={r.id} className="border-b border-af-border px-4 py-3 transition-colors hover:bg-af-surface/40">
                  <div className="flex gap-3">
                    <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-af-surface-2">
                      {r.profiles?.avatar_url ? (
                        <img src={r.profiles.avatar_url} alt="" className="h-full w-full object-cover" />
                      ) : (
                        <div className="h-full w-full bg-gradient-to-br from-af-accent to-af-accent-2" />
                      )}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-1 text-[15px]">
                        <span className="truncate font-bold text-af-text">{r.profiles?.display_name || r.profiles?.username || "Unknown"}</span>
                        <span className="truncate text-af-muted">@{r.profiles?.username || "unknown"}</span>
                        <span className="text-af-muted">·</span>
                        <span className="text-af-muted">{new Date(r.created_at).toLocaleString()}</span>
                      </div>
                      <p className="mt-1 whitespace-pre-wrap break-words text-[15px] leading-normal text-af-text">{r.content}</p>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </div>
      )}
    </Shell>
  );
}

export default function PostPage() {
  return (
    <Suspense fallback={<div className="p-8 text-center text-sm text-af-muted">Loading…</div>}>
      <PostPageInner />
    </Suspense>
  );
}

"use client";
import { useEffect, useState } from "react";
import { Suspense } from "react";
import { useParams } from "next/navigation";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { useAuth } from "@/components/AuthProvider";
import { createClient } from "@/lib/supabase/client";
import Link from "next/link";
import PostCard from "@/components/PostCard";

type Profile = { id: string; username: string; display_name: string | null; bio: string | null; avatar_url: string | null; banner_url: string | null; website: string | null; created_at: string };

function PublicProfileInner() {
  const { username } = useParams<{ username: string }>();
  const { user } = useAuth();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [isSelf, setIsSelf] = useState(false);
  const [following, setFollowing] = useState(false);
  const [followerCount, setFollowerCount] = useState(0);
  const [followingCount, setFollowingCount] = useState(0);

  useEffect(() => {
    const run = async () => {
      const supabase = createClient();
      if (!supabase) { setError("Supabase not configured."); setLoading(false); return; }
      const { data: p } = await supabase.from("profiles").select("*").ilike("username", username).maybeSingle();
      if (!p) { setError("User not found."); setLoading(false); return; }
      setProfile(p as Profile);
      setIsSelf(user?.id === p.id);
      const { data: ps } = await supabase.from("posts").select("*").eq("author_id", p.id).order("created_at", { ascending: false });
      const mapped = (ps ?? []).map((x: any) => ({ ...x, profiles: p }));
      setPosts(mapped);
      const { count: fc } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("following_id", p.id);
      const { count: fingc } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("follower_id", p.id);
      setFollowerCount(fc ?? 0);
      setFollowingCount(fingc ?? 0);
      if (user && user.id !== p.id) {
        const { data: f } = await supabase.from("follows").select("*").eq("follower_id", user.id).eq("following_id", p.id).maybeSingle();
        setFollowing(!!f);
      }
      setLoading(false);
    };
    run();
  }, [username, user]);

  async function toggleFollow() {
    const supabase = createClient();
    if (!supabase || !user || !profile || isSelf) return;
    if (following) {
      await supabase.from("follows").delete().eq("follower_id", user.id).eq("following_id", profile.id);
      setFollowing(false);
      setFollowerCount((c) => Math.max(0, c - 1));
    } else {
      await supabase.from("follows").insert({ follower_id: user.id, following_id: profile.id });
      setFollowing(true);
      setFollowerCount((c) => c + 1);
    }
  }

  if (loading) return <Shell><PageHeader title="Profile" /><div className="p-8 text-center text-sm text-af-muted">Loading…</div></Shell>;
  if (error || !profile) return <Shell><PageHeader title="Profile" /><EmptyState title="User not found" body={error || "This profile may not exist."} /></Shell>;

  return (
    <Shell>
      <PageHeader title={profile.display_name || profile.username} />
      <div className="border-b border-af-border">
        {profile.banner_url ? <img src={profile.banner_url} alt="" className="h-40 w-full object-cover" /> : <div className="h-40 w-full bg-af-surface-2" />}
        <div className="px-4 pb-4">
          <div className="-mt-12 h-24 w-24 overflow-hidden rounded-full border-4 border-af-bg bg-af-surface-2">
            {profile.avatar_url ? <img src={profile.avatar_url} alt="" className="h-full w-full object-cover" /> : null}
          </div>
          <h2 className="mt-2 text-xl font-bold">{profile.display_name || profile.username}</h2>
          <p className="text-af-muted">@{profile.username}</p>
          {profile.bio && <p className="mt-2 text-[15px]">{profile.bio}</p>}
          {profile.website && <a href={profile.website} className="mt-1 block text-af-accent hover:underline" target="_blank" rel="noreferrer">{profile.website}</a>}
          <p className="mt-2 text-sm text-af-muted">Joined {new Date(profile.created_at).toLocaleDateString()}</p>
          <p className="mt-1 text-sm text-af-muted">{followerCount} followers · {followingCount} following</p>
          {isSelf ? (
            <Link href="/settings" className="mt-3 inline-block rounded-full border border-af-border px-4 py-1.5 text-sm font-bold hover:bg-af-surface">Edit Profile</Link>
          ) : user ? (
            <button onClick={toggleFollow} className={`mt-3 rounded-full px-4 py-1.5 text-sm font-bold ${following ? "border border-af-border hover:bg-af-surface" : "bg-af-accent text-white hover:bg-af-accent-hover"}`}>
              {following ? "Following" : "Follow"}
            </button>
          ) : null}
        </div>
      </div>
      <div>
        {posts.length === 0 ? <EmptyState title="No posts yet" body="This user hasn't posted yet." /> : posts.map((p) => <PostCard key={p.id} post={p} />)}
      </div>
    </Shell>
  );
}

export default function PublicProfile() {
  return (
    <Suspense fallback={<div className='p-8 text-center text-sm text-af-muted'>Loading...</div>}><PublicProfileInner /></Suspense>
  );
}

"use client";
import { useEffect, useState } from "react";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { useAuth } from "@/components/AuthProvider";
import { createClient } from "@/lib/supabase/client";
import PostCard from "@/components/PostCard";
import Link from "next/link";

type Profile = { id: string; username: string; display_name: string | null; bio: string | null; avatar_url: string | null; banner_url: string | null; website: string | null; location: string | null; created_at: string };
type Post = { id: string; content: string; created_at: string; author_id: string; media_urls?: string[] | null; profiles?: { username: string; display_name: string | null; avatar_url: string | null } | null };

export default function Profile() {
  const { user } = useAuth();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [posts, setPosts] = useState<Post[]>([]);
  const [reposts, setReposts] = useState<Post[]>([]);
  const [replies, setReplies] = useState<Post[]>([]);
  const [counts, setCounts] = useState({ followers: 0, following: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [tab, setTab] = useState<"posts" | "replies" | "reposts" | "media">("posts");
  const [listType, setListType] = useState<'followers' | 'following' | null>(null);
  const [listProfiles, setListProfiles] = useState<any[]>([]);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState('');
  const [mediaFilter, setMediaFilter] = useState<"all" | "photos" | "gifs" | "videos">("all");

  useEffect(() => {
    const run = async () => {
      const supabase = createClient();
      if (!supabase || !user) {
        setLoading(false);
        return;
      }
      const { data: ps } = await supabase.from("posts").select("*").eq("author_id", user.id).order("created_at", { ascending: false });
      const { data: prof } = await supabase.from("profiles").select("*").eq("id", user.id).maybeSingle();
      let profileData = prof;
      if (!profileData) {
        const { data: np } = await supabase.from("profiles").upsert({ id: user.id, username: user.email?.split("@")[0] || `user_${user.id.slice(0, 6)}` }).select().single();
        profileData = np;
      }
      setProfile(profileData as Profile);
      const mapped = (ps ?? []).map((p: any) => ({ ...p, profiles: profileData }));
      setPosts(mapped as Post[]);

      const { data: r } = await supabase.from("reposts").select("post_id").eq("user_id", user.id);
      const repostIds = (r ?? []).map((x: any) => x.post_id);
      if (repostIds.length) {
        const { data: rp } = await supabase.from("posts").select("*").in("id", repostIds);
        const aIds = [...new Set((rp ?? []).map((x: any) => x.author_id))];
        let pm = new Map();
        if (aIds.length) {
          const { data: profs } = await supabase.from("profiles").select("*").in("id", aIds);
          pm = new Map((profs ?? []).map((x: any) => [x.id, x]));
        }
        const mappedR = (rp ?? []).map((x: any) => ({ ...x, profiles: pm.get(x.author_id) || null }));
        setReposts(mappedR as Post[]);
      } else {
        setReposts([]);
      }

      const { data: rp } = await supabase.from("replies").select("*").eq("author_id", user.id).order("created_at", { ascending: false });
      const mappedReplies = (rp ?? []).map((r: any) => ({ id: r.id, content: r.content, created_at: r.created_at, author_id: r.author_id, profiles: profileData }));
      setReplies(mappedReplies as Post[]);
      const { count: f1 } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("following_id", user.id);
      const { count: f2 } = await supabase.from("follows").select("*", { count: "exact", head: true }).eq("follower_id", user.id);
      setCounts({ followers: f1 ?? 0, following: f2 ?? 0 });
      setLoading(false);
    };
    run();
  }, [user]);

    async function openList(type: 'followers' | 'following') {
    if (!user) return;
    const supabase = createClient();
    if (!supabase) return;
    setListType(type);
    setListLoading(true);
    setListError('');
    setListProfiles([]);
    const column = type === 'followers' ? 'follower_id' : 'following_id';
    const filterColumn = type === 'followers' ? 'following_id' : 'follower_id';
    const targetId = user.id;
    const { data: rows, error } = await supabase.from('follows').select(column).eq(filterColumn, targetId);
    if (error) { setListError(error.message); setListLoading(false); return; }
    const ids = (rows ?? []).map((r: any) => r[column]);
    if (ids.length === 0) { setListLoading(false); return; }
    const { data: profs, error: pError } = await supabase.from('profiles').select('id,username,display_name,avatar_url').in('id', ids);
    if (pError) { setListError(pError.message); setListLoading(false); return; }
    setListProfiles(profs ?? []);
    setListLoading(false);
  }

  if (!user) {
    return (
      <Shell>
        <PageHeader title="Profile" />
        <EmptyState title="Sign in to view your profile" body="Create an account or sign in to manage your profile." action={{ label: "Sign in", href: "/signin" }} />
      </Shell>
    );
  }

  return (
    <Shell>
      <PageHeader title="Profile" />
      {loading ? (
        <div className="p-8 text-center text-sm text-af-muted">Loading…</div>
      ) : error ? (
        <div className="p-8 text-center text-sm text-af-danger">{error}</div>
      ) : !profile ? (
        <EmptyState title="Complete your profile" body="Add your details to help the community find you." action={{ label: "Edit profile", href: "/settings" }} />
      ) : (
        <div>
          <div className="relative">
            {profile.banner_url ? (
              <img src={profile.banner_url} alt="" className="h-48 w-full object-cover" />
            ) : (
              <div className="h-48 w-full bg-af-surface-2" />
            )}
            <div className="absolute -bottom-16 left-4">
              {profile.avatar_url ? (
                <img src={profile.avatar_url} alt="" className="h-32 w-32 rounded-full border-4 border-af-bg object-cover" />
              ) : (
                <div className="h-32 w-32 rounded-full border-4 border-af-bg bg-af-surface-2" />
              )}
            </div>
          </div>
          <div className="px-4 pb-4 pt-20">
            <div className="flex items-start justify-between">
              <div>
                <h2 className="text-xl font-extrabold">{profile.display_name || profile.username}</h2>
                <p className="text-[15px] text-af-muted">@{profile.username}</p>
              </div>
              <Link href="/settings" className="rounded-full border border-af-border px-4 py-1.5 text-[15px] font-bold transition-colors hover:bg-af-surface-2">
                Edit profile
              </Link>
            </div>
            {profile.bio && <p className="mt-3 whitespace-pre-wrap text-[15px]">{profile.bio}</p>}
            <div className="mt-3 flex flex-wrap gap-3 text-[15px] text-af-muted">
              {profile.location && <span>📍 {profile.location}</span>}
              {profile.website && (
                <a href={profile.website} className="text-af-accent hover:underline">
                  🔗 {profile.website.replace(/^https?:\/\//, "")}
                </a>
              )}
              <span>📅 Joined {new Date(profile.created_at).toLocaleDateString()}</span>
            </div>
            <div className="mt-3 flex gap-4 text-[15px]">
              <span>
                <strong>{counts.following}</strong> <span className="text-af-muted">Following</span>
              </span>
              <span>
                <strong>{counts.followers}</strong> <span className="text-af-muted">Followers</span>
              </span>
            </div>
          </div>
          <div className="flex border-b border-af-border">
            {(["posts", "replies", "reposts", "media"] as const).map((t) => (
              <button
                key={t}
                onClick={() => setTab(t)}
                className={`relative flex-1 py-4 text-[15px] font-medium capitalize transition-colors hover:bg-af-surface-2 ${
                  tab === t ? "font-bold text-af-text" : "text-af-muted"
                }`}
              >
                {t}
                {tab === t && <div className="absolute bottom-0 left-1/2 h-1 w-14 -translate-x-1/2 rounded-full bg-af-brand" />}
              </button>
            ))}
          </div>
          {tab === "media"
            ? (() => {
                const items = Array.from(new Map<string, { url: string; post: Post }>(posts.flatMap((p) => (p.media_urls ?? []).map((u) => [u, { url: u, post: p }]))).values());
                const filtered = items.filter((it) => {
                  const isGif = it.url.toLowerCase().endsWith(".gif");
                  const isVideo = /\.(mp4|webm|mov)$/i.test(it.url);
                  if (mediaFilter === "photos") return !isGif && !isVideo;
                  if (mediaFilter === "gifs") return isGif;
                  if (mediaFilter === "videos") return isVideo;
                  return true;
                });
                return (
                  <div className="p-4">
                    <div className="mb-4 flex gap-2 text-[13px]">
                      {(["all", "photos", "gifs", "videos"] as const).map((f) => (
                        <button
                          key={f}
                          onClick={() => setMediaFilter(f)}
                          className={`rounded-full px-3 py-1 transition-colors ${
                            mediaFilter === f ? "bg-af-brand text-white" : "bg-af-surface-2 text-af-text hover:bg-af-surface-3"
                          }`}
                        >
                          {f}
                        </button>
                      ))}
                    </div>
                    {filtered.length === 0 ? (
                      <EmptyState title="No media yet" body="Media you post will appear here." />
                    ) : (
                      <div className="grid grid-cols-3 gap-0.5">
                        {filtered.map((it, i) => (
                          <Link key={it.url + i} href={`/posts/${it.post.id}`} className="aspect-square overflow-hidden bg-af-surface-2">
                            {/\.(mp4|webm|mov)$/i.test(it.url) ? (
                              <div className="relative h-full w-full">
                                <video src={it.url} className="h-full w-full object-cover" />
                                <span className="absolute inset-0 flex items-center justify-center text-4xl text-white drop-shadow-lg">▶</span>
                              </div>
                            ) : (
                              <img src={it.url} alt="" className="h-full w-full object-cover" />
                            )}
                          </Link>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })()
            : tab === "replies"
            ? replies.length === 0 ? (
                <EmptyState title="No replies yet" body="Your replies will appear here." />
              ) : (
                <div>
                  {replies.map((p) => (
                    <PostCard key={p.id} post={p} />
                  ))}
                </div>
              )
            : tab === "reposts"
            ? reposts.length === 0 ? (
                <EmptyState title="No reposts yet" body="Posts you repost will appear here." />
              ) : (
                <div>
                  {reposts.map((p) => (
                    <PostCard key={p.id} post={p} repostedBy="You" />
                  ))}
                </div>
              )
            : tab !== "posts"
            ? <EmptyState title="Nothing here yet" body="This tab will populate as features connect to real data." />
            : posts.length === 0 ? (
                <EmptyState title="No posts yet" body="Your posts will appear here." />
              ) : (
                <div>
                  {posts.map((p) => (
                    <PostCard key={p.id} post={p} />
                  ))}
                </div>
              )}
        </div>
      )}
    </Shell>
  );
}

﻿"use client";
import { useEffect, useState } from "react";
import { Shell, PageHeader, EmptyState } from "@/components/Shell";
import { useAuth } from "@/components/AuthProvider";
import { createClient } from "@/lib/supabase/client";

type Profile = { username: string; display_name: string | null; bio: string | null; location: string | null; website: string | null; avatar_url: string | null; banner_url: string | null };

export default function Settings() {
  const { user } = useAuth();
  const [saved, setSaved] = useState<Profile>({ username: "", display_name: "", bio: "", location: "", website: "", avatar_url: null, banner_url: null });
  const [form, setForm] = useState<Profile>({ username: "", display_name: "", bio: "", location: "", website: "", avatar_url: null, banner_url: null });
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [bannerPreview, setBannerPreview] = useState<string | null>(null);
  const [msg, setMsg] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const supabase = createClient();
    if (!supabase || !user) return;
    supabase.from("profiles").select("*").eq("id", user.id).maybeSingle().then(({ data }: any) => {
      if (data) {
        const p: Profile = {
          username: data.username || "",
          display_name: data.display_name || "",
          bio: data.bio || "",
          location: data.location || "",
          website: data.website || "",
          avatar_url: data.avatar_url || null,
          banner_url: data.banner_url || null,
        };
        setSaved(p);
        setForm(p);
      }
    });
  }, [user]);

  const dirty = JSON.stringify(form) !== JSON.stringify(saved);

  async function compressImage(file: File): Promise<File> {
    if (file.size < 5 * 1024 * 1024) return file;
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        let { width, height } = img;
        const maxDim = 2048;
        if (width > maxDim || height > maxDim) {
          const scale = Math.min(maxDim / width, maxDim / height);
          width = Math.round(width * scale);
          height = Math.round(height * scale);
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        if (!ctx) { reject(new Error("Canvas not supported")); return; }
        ctx.drawImage(img, 0, 0, width, height);
        canvas.toBlob((blob) => {
          if (!blob) { reject(new Error("Compression failed")); return; }
          resolve(new File([blob], file.name.replace(/\.[^.]+$/, ".webp"), { type: "image/webp" }));
        }, "image/webp", 0.8);
      };
      img.onerror = () => reject(new Error("Invalid image"));
      img.src = URL.createObjectURL(file);
    });
  }

  async function upload(file: File, bucket: string) {
    const supabase = createClient();
    if (!supabase || !user) throw new Error("Not signed in");
    if (!file.type.startsWith("image/")) throw new Error("File must be an image");
    const processed = await compressImage(file);
    if (processed.size >= 5 * 1024 * 1024) throw new Error("Image must be under 5MB");
    const ext = processed.name.split(".").pop();
    const path = `${user.id}/${Date.now()}.${ext}`;
    const { error } = await supabase.storage.from(bucket).upload(path, processed, { upsert: true });
    if (error) throw error;
    const { data } = supabase.storage.from(bucket).getPublicUrl(path);
    return data.publicUrl;
  }

  async function onAvatarChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      if (!file.type.startsWith("image/")) throw new Error("File must be an image");
      setAvatarPreview(URL.createObjectURL(file));
      const url = await upload(file, "avatars");
      setForm((f) => ({ ...f, avatar_url: url }));
      setMsg("");
    } catch (err: any) { setError(err.message); setAvatarPreview(null); }
  }

  async function onBannerChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      if (!file.type.startsWith("image/")) throw new Error("File must be an image");
      setBannerPreview(URL.createObjectURL(file));
      const url = await upload(file, "banners");
      setForm((f) => ({ ...f, banner_url: url }));
      setMsg("");
    } catch (err: any) { setError(err.message); setBannerPreview(null); }
  }

  async function save(e: React.FormEvent) {
    e.preventDefault();
    setError(""); setMsg("");
    const supabase = createClient();
    if (!supabase || !user) { setError("Sign in required."); return; }
    const usernameClean = form.username.trim().toLowerCase();
    if (!/^[a-z0-9_]{3,20}$/i.test(usernameClean)) { setError("Username must be 3-20 characters (letters, numbers, underscore)."); return; }
    if (usernameClean !== saved.username) {
      const { data: existing } = await supabase.from("profiles").select("id").ilike("username", usernameClean).neq("id", user.id).maybeSingle();
      if (existing) { setError("That username is already taken."); return; }
    }
    setLoading(true);
    const { error } = await supabase.from("profiles").update({ username: usernameClean, display_name: form.display_name, bio: form.bio, location: form.location, website: form.website, avatar_url: form.avatar_url, banner_url: form.banner_url }).eq("id", user.id);
    setLoading(false);
    if (error) setError(error.message);
    else { setSaved({ ...form, username: usernameClean }); setMsg("Profile saved."); }
  }

  function cancel() {
    setForm(saved);
    setAvatarPreview(null);
    setBannerPreview(null);
    setMsg("");
    setError("");
  }

  if (!user) return <Shell><PageHeader title="Settings" /><EmptyState title="Sign in to manage settings" body="Account settings require authentication." action={{ label: "Sign in", href: "/signin" }} /></Shell>;

  return (
    <Shell>
      <PageHeader title="Settings" />
      <section className="p-4 max-w-2xl">
        <h2 className="text-lg font-semibold">Profile</h2>
        <p className="text-sm text-af-muted">Manage how your profile appears to others.</p>
        <form onSubmit={save} className="mt-6 space-y-6">
          <div className="rounded-xl border border-af-border bg-af-surface p-4">
            <label className="block cursor-pointer">
              <div className="h-32 rounded-lg bg-af-surface-2 overflow-hidden flex items-center justify-center">
                {(bannerPreview || form.banner_url) ? <img src={bannerPreview || form.banner_url!} alt="" className="h-full w-full object-cover" /> : <span className="text-sm text-af-muted">Choose banner image</span>}
              </div>
              <input type="file" accept="image/*" onChange={onBannerChange} className="hidden" />
            </label>
            <p className="mt-2 text-xs text-af-muted">PNG, JPG or WebP, up to 5MB.</p>
          </div>
          <div className="flex items-center gap-4">
            <label className="cursor-pointer">
              <div className="h-16 w-16 rounded-full bg-af-surface-2 overflow-hidden flex items-center justify-center">
                {(avatarPreview || form.avatar_url) ? <img src={avatarPreview || form.avatar_url!} alt="" className="h-full w-full object-cover" /> : <span className="text-xs text-af-muted">+</span>}
              </div>
              <input type="file" accept="image/*" onChange={onAvatarChange} className="hidden" />
            </label>
            <div>
              <p className="text-sm font-medium">Avatar</p>
              <p className="text-xs text-af-muted">Click to choose an image. PNG, JPG or WebP, up to 5MB.</p>
            </div>
          </div>
          <div>
            <label className="block text-xs text-af-muted mb-1">Username</label>
            <input value={form.username || ""} onChange={(e) => setForm({ ...form, username: e.target.value })} className="w-full rounded-lg border border-af-border bg-af-surface px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block text-xs text-af-muted mb-1">Display name</label>
            <input value={form.display_name || ""} onChange={(e) => setForm({ ...form, display_name: e.target.value })} className="w-full rounded-lg border border-af-border bg-af-surface px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block text-xs text-af-muted mb-1">Bio</label>
            <textarea value={form.bio || ""} onChange={(e) => setForm({ ...form, bio: e.target.value })} className="w-full rounded-lg border border-af-border bg-af-surface px-3 py-2 text-sm" rows={4} maxLength={160} />
            <div className="text-xs text-af-muted text-right">{(form.bio || "").length}/160</div>
          </div>
          <div>
            <label className="block text-xs text-af-muted mb-1">Location</label>
            <input value={form.location || ""} onChange={(e) => setForm({ ...form, location: e.target.value })} className="w-full rounded-lg border border-af-border bg-af-surface px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block text-xs text-af-muted mb-1">Website</label>
            <input value={form.website || ""} onChange={(e) => setForm({ ...form, website: e.target.value })} className="w-full rounded-lg border border-af-border bg-af-surface px-3 py-2 text-sm" />
          </div>
          {error && <p className="text-sm text-af-danger">{error}</p>}
          {msg && <p className="text-sm text-af-muted">{msg}</p>}
          <div className="flex gap-3">
            <button disabled={loading || !dirty} className="rounded-full bg-af-accent px-4 py-1.5 text-sm font-semibold text-black disabled:opacity-40">{loading ? "Saving..." : "Save"}</button>
            <button type="button" onClick={cancel} disabled={loading} className="rounded-full border border-af-border px-4 py-1.5 text-sm font-semibold hover:bg-af-surface-2">Cancel</button>
          </div>
        </form>
      </section>
    </Shell>
  );
}

